// NTP Time for Online Arduino Compilers (ESP32)
#include <WiFi.h>
#include <time.h>

// 1. Замените значения ниже на ваш SSID и пароль
const char* ssid = "YOUR_WIFI_SSID";
const char* password = "YOUR_WIFI_PASSWORD";

// Адрес сервера времени
const char* ntpServer = "pool.ntp.org";

// 2. Настройте часовой пояс (в секундах)
// Пример: Москва UTC+3 -> 3 * 3600 = 10800
//          Берлин UTC+1/CET -> 1 * 3600 = 3600 (летом +7200)
const long gmtOffsetSec = 3 * 3600; 
// Смещение летнего времени (если сервер сам его не учитывает)
const int daylightOffsetSec = 0; 

void setup() {
  Serial.begin(115200);

  // Подключение к WiFi
  Serial.println("Connecting to WiFi");
  WiFi.begin(ssid, password);

  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println("\nWiFi connected!");

  // Инициализация NTP
  configTime(gmtOffsetSec, daylightOffsetSec, ntpServer);
  Serial.println("Waiting for time sync...");
}

void loop() {
  struct tm timeinfo;

  // Проверяем, пришло ли время. Если нет - ждем.
  if (!getLocalTime(&timeinfo)) {
    Serial.println("Failed to obtain time! Retrying in 2 seconds...");
    delay(2000);
    return;
  }

  // Формируем строку вида: 2026-09-04 15:30:25 Friday
  char buffer[80];
  strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S %A", &timeinfo);

  Serial.println(buffer);

  // Повторяем раз в секунду
  delay(1000);
}
